return ['domain'=>'blockstudio','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'syr','project-id-version'=>'Blockstudio','po-revision-date'=>'2026-10-23 15:38+0000','messages'=>['Blockstudio'=>'Blockstudio','The "%1$s" attribute on a %2$s block tag is dropped because the block declares no field with that id. Declare the field, or write it as a data-, aria- or html- attribute to put it on the root element.'=>'ܐܬܬܪܣܝ ܬܚܘܡܐ «%1$s» ܕܥܠ ܪܡܙܐ ܕܦܘܪܫܐ %2$s، ܡܛܠ ܕܦܘܪܫܐ ܠܐ ܡܟܪܙ ܚܕ ܚܩܠܐ ܒܗܘ ܡܗܝܐ. ܟܪܘܙ ܚܩܠܐ، ܐܘ ܟܬܘܒܝܗ ܐܝܟ ܬܚܘܡܐ ܕ-data- ܐܘ aria- ܐܘ html- ܠܡܣܡܗ ܥܠ ܐܣܝܣܐ.','This storage key is not declared by the block or its extensions.'=>'ܗܢܐ ܩܠܝܕܐ ܕܐܘܣܪܐ ܠܐ ܡܟܪܙ ܡܢ ܦܘܪܫܐ ܐܘ ܡܢ ܬܘܣܦܬܗ.','This top-level key is not an attribute of the block, so it is ignored.'=>'ܗܢܐ ܩܠܝܕܐ ܕܪܝܫܐ ܠܐ ܗܘ ܐܬܪܝܒܘܬܐ ܕܒܠܘܟ، ܘܡܛܠ ܗܕܐ ܡܬܥܒܪ.','This key is only read inside the blockstudio object, which is missing.'=>'ܗܢܐ ܩܠܝܕܐ ܡܬܩܪܐ ܒܠܚܘܕ ܓܘ ܐܘܒܝܩܛܐ ܕـblockstudio، ܕܠܝܬܘܗܝ.','This value is not among the field options.'=>'ܗܢܐ ܛܝܡܐ ܠܐ ܡܢ ܒܝܢܬ ܓܒܝ̈ܬܐ ܕܚܩܠܐ.','This value has an unsupported shape for the field.'=>'ܗܢܐ ܛܝܡܐ ܠܝܬ ܠܗ ܨܘܪܬܐ ܕܡܣܡܟܐ ܠܚܩܠܐ.','This repeater has fewer rows than its minimum.'=>'ܠܗܢܐ ܡܟܬܒܢܐ ܐܝܬ ܦܚܘܬ ܣܛܘܪ̈ܐ ܡܢ ܡܨܥܝܐ.','This repeater has more rows than its maximum.'=>'ܠܗܢܐ ܡܟܬܒܢܐ ܐܝܬ ܝܬܝܪ ܣܛܘܪ̈ܐ ܡܢ ܪܒܐ.','This storage key has conflicting field definitions.'=>'ܠܗܢܐ ܩܠܝܕܐ ܕܐܘܣܪܐ ܐܝܬ ܦܘܫܟܐ ܒܦܘܪ̈ܫܐ ܕܚܩܠܐ.','The nested field value overrides this top-level value.'=>'ܛܝܡܐ ܕܚܩܠܐ ܓܘܝܐ ܡܚܠܦ ܠܗܢܐ ܛܝܡܐ ܕܠܥܠ.','Extension bindings read this value only from blockstudio.attributes.'=>'ܐܣܝܣ̈ܐ ܕܬܘܣܦܬܐ ܩܪܝܢ ܠܗܢܐ ܛܝܡܐ ܐܚܘܕܐܝܬ ܡܢ blockstudio.attributes.','Blockstudio field values must be stored in an object.'=>'ܛܝܡ̈ܐ ܕܚܩܠ̈ܐ ܕBlockstudio ܚܝܒܝܢ ܕܢܗܘܘܢ ܡܬܚܙܝܢ ܒܓܘ ܚܕ ܐܣܟܡܐ.','Blockstudio is preparing its block cache. Please retry shortly.'=>'Blockstudio ܡܛܝܒܐ ܠܡܚܕܬܘ ܠܡܣܓܠܐ ܕܦܘܪ̈ܫܐ. ܒܥܝܢܐ ܢܣܝ ܬܘܒ ܒܩܠܝܠ.','Canvas is disabled.'=>'ܩܢܘܣܐ ܠܐ ܡܦܥܠ.','Invalid or missing CSRF token.'=>'ܢܣܒܐ CSRF ܠܐ ܩܢܝܢܐ ܐܘ ܚܣܝܪܐ.','Authentication required.'=>'ܡܛܠܒܐ ܗܝܡܢܘܬܐ.','Insufficient permissions.'=>'ܠܝܬ ܪܫܝܢ̈ܐ ܣܦܩ̈ܐ.','Validation failed.'=>'ܒܘܚܢܐ ܠܐ ܡܛܝܒ.','Record not found.'=>'ܠܐ ܐܫܬܟܚ ܣܓܠܐ.','Invalid islands request.'=>'ܒܥܝܬܐ ܕܓܙܪ̈ܬܐ ܠܐ ܩܢܝܢܬܐ.','Too many islands requested.'=>'ܐܬܒܥܝܘ ܓܙܪ̈ܬܐ ܣܓܝܐ̈ܬܐ ܡܢ ܡܕܝܢܬܐ.','Invalid island block.'=>'ܓܙܪܬܐ ܕܦܘܪܫܐ ܠܐ ܩܢܝܢܬܐ.','Invalid island signature.'=>'ܚܬܡܐ ܕܓܙܪܬܐ ܠܐ ܩܢܝܢܐ.','Sorry, you are not allowed to read blocks of this post.'=>'ܚܣܐ، ܠܐ ܡܫܬܡܠܐ ܠܟ ܕܬܩܪܐ ܠܦܘܪ̈ܫܐ ܕܗܢܐ ܦܘܣܛܐ.','Sorry, you are not allowed to read blocks as this user.'=>'ܚܣܐ، ܠܐ ܡܫܬܡܠܐ ܠܟ ܕܬܩܪܐ ܠܦܘܪ̈ܫܐ ܐܝܟ ܗܢܐ ܡܦܠܚܢܐ.','Invalid block.'=>'ܦܘܪܫܐ ܠܐ ܩܢܝܢܐ.','Method not allowed.'=>'ܐܘܪܚܐ ܠܐ ܡܫܬܡܠܐ.','Block not found.'=>'ܦܘܪܫܐ ܠܐ ܐܫܬܟܚ.','Function not found.'=>'ܦܘܥܠܐ ܠܐ ܐܫܬܟܚ.','Function is not callable.'=>'ܠܐ ܡܫܬܡܠܐ ܠܡܩܪܝܘ ܦܘܥܠܐ.','Blockstudio ignored invalid configuration values:'=>'Blockstudio ܫܒܩ ܛܝܡ̈ܐ ܕܛܘܟܣܐ ܕܠܐ ܩܢܝ̈ܢܐ:','%s: Link text'=>'%s: ܟܬܒܬܐ ܕܐܣܪܐ','%s: URL'=>'%s: URL','True'=>'ܫܪܝܪܐ','False'=>'ܕܓܠܐ','Could not load database records.'=>'ܠܐ ܡܨܐ ܠܡܛܥܢ ܣܓܠ̈ܐ ܕܡܓܪܬܐ.','This database has no records yet.'=>'ܠܡܓܪܬܐ ܠܐ ܐܝܬ ܣܓܠ̈ܐ ܗܫܐ.','No Blockstudio databases are registered.'=>'ܠܐ ܐܬܣܓܠܘ ܡܓܪ̈ܬܐ ܕBlockstudio.','The selected database could not be found.'=>'ܠܐ ܐܫܟܚ ܠܡܓܪܬܐ ܕܐܬܓܒܝܬ.','Overview'=>'ܚܘܪܝܐ ܟܠܢܝܐ','Registry'=>'ܡܣܓܠܐ','Databases'=>'ܡܓܪ̈ܬܐ','Docs'=>'ܟܬܒ̈ܐ','No Blockstudio overview data is available.'=>'ܠܐ ܐܝܬ ܡܕܥ̈ܐ ܕܚܘܪܝܐ ܟܠܢܝܐ ܕBlockstudio.','Name'=>'ܫܡܐ','Title'=>'ܟܘܢܝܐ','Description'=>'ܬܘܕܝܬܐ','Category'=>'ܣܕܪܐ','Type'=>'ܙܢܐ','Status'=>'ܐܝܟܢܝܘܬܐ','Installed'=>'ܡܬܩܢܐ','Available'=>'ܡܛܝܒܐ','Actions'=>'ܦܘܠܚܢ̈ܐ','Reimport'=>'ܫܢܝ ܬܘܒ','Import'=>'ܥܒܪ','No registries are configured. Add registries to your theme\'s blocks.json file.'=>'ܠܐ ܡܛܘܟܣܝܢ ܡܣܓܠ̈ܐ. ܐܘܣܦ ܡܣܓܠ̈ܐ ܠܦܨܠܐ ܕܬܝܡܐ ܒܟܬܒܐ blocks.json.','Search blocks'=>'ܒܨܝ ܦܘܪ̈ܫܐ','No blocks are registered.'=>'ܠܐ ܐܬܣܓܠܘ ܦܘܪ̈ܫܐ.','API'=>'API','Render'=>'ܨܘܪ','Attributes'=>'ܬܚܘܡ̈ܐ','Blocks'=>'ܦܘܪ̈ܫܐ','No extensions are registered.'=>'ܠܐ ܐܬܣ